"""Production cold-start receiver gates and async completion, without starting a UI/root process."""
from pathlib import Path
import subprocess,tempfile,xml.etree.ElementTree as ET
root=Path(__file__).resolve().parents[1]
sources={
'android/content/Intent.java':'package android.content;public class Intent {public static final String ACTION_BOOT_COMPLETED="boot";private String action;public Intent(String a){action=a;}public String getAction(){return action;}}',
'android/content/Context.java':'package android.content;public class Context {public android.os.UserManager user=new android.os.UserManager();public <T>T getSystemService(Class<T> type){return type.cast(user);}public Context getApplicationContext(){return this;}}',
'android/content/BroadcastReceiver.java':'package android.content;public abstract class BroadcastReceiver {public static volatile int pending,finished;public abstract void onReceive(Context c,Intent i);public PendingResult goAsync(){pending++;return new PendingResult();}public static class PendingResult{public void finish(){finished++;}}}',
'android/os/UserManager.java':'package android.os;public class UserManager {public boolean unlocked=true;public boolean isUserUnlocked(){return unlocked;}}',
'android/os/Build.java':'package android.os;public class Build {public static String MODEL="NX809J",DEVICE="NX809J";public static class VERSION{public static int SDK_INT=36;}}',
'android/os/Process.java':'package android.os;public class Process {public static int uid=10123;public static int myUid(){return uid;}}',
'android/os/Looper.java':'package android.os;public class Looper {public static Looper getMainLooper(){return new Looper();}}',
'android/os/Handler.java':'package android.os;public class Handler {public Handler(Looper l){}public void post(Runnable r){r.run();}}',
'com/elitedarkkaiser/nubialy/GuardReader.java':'package com.elitedarkkaiser.nubialy;public class GuardReader {public static String id="enabled";public static String inspectEnabled(){return id;}}',
'com/elitedarkkaiser/nubialy/RecoveryStore.java':'package com.elitedarkkaiser.nubialy;public class RecoveryStore {public static boolean allowed=true;public static boolean enabledAllowed(android.content.Context c,String id){return allowed&&"enabled".equals(id);}}',
'com/elitedarkkaiser/nubialy/SystemUiGuardClient.java':'package com.elitedarkkaiser.nubialy;public class SystemUiGuardClient {public static volatile int calls;public static boolean delay;public static java.util.function.Consumer<String> reply;public SystemUiGuardClient(android.content.Context c){}public void preview(String operation,java.util.function.Consumer<String> cb){if(!operation.equals("clock_resume"))throw new AssertionError();calls++;if(delay)reply=cb;else cb.accept("done");}}',
'com/elitedarkkaiser/nubialy/FingerprintServiceClient.java':'package com.elitedarkkaiser.nubialy;public class FingerprintServiceClient {public static int calls;public FingerprintServiceClient(android.content.Context c){}public void check(java.util.function.Consumer<String> cb){calls++;cb.accept("done");}}',
'com/elitedarkkaiser/nubialy/LauncherServiceClient.java':'package com.elitedarkkaiser.nubialy;public class LauncherServiceClient {public static int calls;public LauncherServiceClient(android.content.Context c){}public void check(java.util.function.Consumer<String> cb){calls++;cb.accept("done");}}',
'com/elitedarkkaiser/nubialy/BootResumeTest.java':'''package com.elitedarkkaiser.nubialy;import android.content.*;public class BootResumeTest {static void check(boolean b){if(!b)throw new AssertionError();}static void waitFor(java.util.function.BooleanSupplier done)throws Exception{long until=System.nanoTime()+2000000000L;while(!done.getAsBoolean()){if(System.nanoTime()>until)throw new AssertionError("timeout");Thread.sleep(2);}}public static void main(String[] a)throws Exception{Context context=new Context();var receiver=new BootResumeReceiver();Intent boot=new Intent(Intent.ACTION_BOOT_COMPLETED),module=new Intent(BootResumeReceiver.ACTION);receiver.onReceive(context,null);receiver.onReceive(context,new Intent("other"));context.user.unlocked=false;receiver.onReceive(context,boot);context.user.unlocked=true;android.os.Process.uid=110123;receiver.onReceive(context,boot);android.os.Process.uid=10123;android.os.Build.MODEL="other";android.os.Build.DEVICE="other";receiver.onReceive(context,boot);android.os.Build.MODEL="NX809J";android.os.Build.DEVICE="NX809J";check(BroadcastReceiver.pending==0);RecoveryStore.allowed=false;receiver.onReceive(context,boot);waitFor(()->BroadcastReceiver.finished==1);check(SystemUiGuardClient.calls==0);RecoveryStore.allowed=true;GuardReader.id=null;receiver.onReceive(context,module);waitFor(()->BroadcastReceiver.finished==2);check(SystemUiGuardClient.calls==0);GuardReader.id="enabled";receiver.onReceive(context,boot);waitFor(()->BroadcastReceiver.finished==3);check(SystemUiGuardClient.calls==1&&FingerprintServiceClient.calls==1&&LauncherServiceClient.calls==1);SystemUiGuardClient.delay=true;receiver.onReceive(context,module);waitFor(()->SystemUiGuardClient.calls==2);receiver.onReceive(context,module);check(BroadcastReceiver.pending==4);SystemUiGuardClient.reply.accept("done");waitFor(()->BroadcastReceiver.finished==4);check(FingerprintServiceClient.calls==2&&LauncherServiceClient.calls==2);System.out.println("Background resume passed: unlock/device/user/action/authority gates, no implicit enable, duplicate coalescing and async completion");}}'''
}
with tempfile.TemporaryDirectory(prefix='nubialy-boot-receiver-') as work:
 w=Path(work)
 for name,text in sources.items():
  p=w/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
 files=[str(p) for p in w.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy'/n) for n in ['BootResumeReceiver.java','CompatibilityPolicy.java']]
 subprocess.run(['java','com.sun.tools.javac.Main','-d',str(w/'classes'),*files],check=True)
 subprocess.run(['java','-cp',str(w/'classes'),'com.elitedarkkaiser.nubialy.BootResumeTest'],check=True)
ns='{http://schemas.android.com/apk/res/android}'
m=ET.parse(root/'app/src/main/AndroidManifest.xml');receiver=next(e for e in m.findall('./application/receiver') if e.attrib[ns+'name']=='.BootResumeReceiver');assert receiver.attrib[ns+'permission']=='com.elitedarkkaiser.nubialy.permission.GUARD_DIAGNOSTIC';assert receiver.attrib.get(ns+'directBootAware')!='true';assert any(e.attrib[ns+'name']=='android.permission.RECEIVE_BOOT_COMPLETED' for e in m.findall('uses-permission'))
